import sys

def solve():
    n = int(sys.stdin.readline())
    b = list(map(int, sys.stdin.readline().split()))

    if n == 2:
        if b[0] == b[1]:
            print("NO")
            return
        else:
            x = b[0]
            y = b[1]
            if x < y:
                print("YES")
                print(x, y)
            else:
                print("YES")
                print(y, x)
            return

    a = [0] * n
    a[0] = b[0] + b[1]
    a[1] = b[1]

    for i in range(2, n):
        a[i] = b[i] + a[i-1]

    if a[-1] % a[0] != b[-1]:
        print("NO")
        return

    for i in range(n):
        if a[i] % a[(i+1)%n] != b[i]:
            print("NO")
            return

    print("YES")
    print(' '.join(map(str, a)))

solve()
